begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
update private.organizer_policy_release_settings set environment='unconfigured';
insert into auth.users(id,email) values ('16160000-0000-4000-8000-000000000001','draft-owner@example.invalid'),('16160000-0000-4000-8000-000000000002','draft-foreign@example.invalid');
insert into public.organizers(id,display_name) values ('16160000-0000-4000-8000-000000000001','Draft owner'),('16160000-0000-4000-8000-000000000002','Foreign owner');
select set_config('request.jwt.claim.sub','16160000-0000-4000-8000-000000000001',true);
insert into public.events(id,organizer_id,title) values ('16160000-0000-4000-8000-000000000010','16160000-0000-4000-8000-000000000001','New draft');
set local role authenticated;
select lives_ok($$select public.get_owned_event_change_context('16160000-0000-4000-8000-000000000010')$$,'owner can load new draft without publication policy');
select is(public.get_owned_event_change_context('16160000-0000-4000-8000-000000000010')->'requirements'->>'policies_unavailable','true','read explicitly reports unavailable policies');
select is(public.get_owned_event_change_context('16160000-0000-4000-8000-000000000010')->'requirements'->>'needs_acceptance','true','read never fabricates consent');
select lives_ok($$select public.save_owned_event_revision_if_current('16160000-0000-4000-8000-000000000010','{"title": "Updated draft", "description": null, "category": null, "starts_at": null, "ends_at": null, "timezone": "America/Los_Angeles", "venue_name": null, "address_line1": null, "address_line2": null, "city": null, "region": null, "postal_code": null, "country_code": "US", "mapbox_feature_id": null, "latitude": null, "longitude": null, "admission_type": "free", "capacity": null}'::jsonb,public.get_owned_event_change_context('16160000-0000-4000-8000-000000000010')->>'context_token')$$,'conditional draft save works without policies');
select is(public.get_owned_event_change_context('16160000-0000-4000-8000-000000000010')->'event'->>'title','Updated draft','reopening returns saved title');
select lives_ok($$select public.save_owned_event_requirements_if_current('16160000-0000-4000-8000-000000000010','{"minimum_age":"all_ages","alcohol_present":false,"cannabis_present":false,"explicit_adult_content":false,"gambling_present":false,"weapons_present":false,"high_risk_activity":false}'::jsonb,public.get_owned_event_change_context('16160000-0000-4000-8000-000000000010')->>'context_token')$$,'disclosure save works without publication readiness');
select is(public.get_owned_event_change_context('16160000-0000-4000-8000-000000000010')->'requirements'->>'minimum_age','all_ages','saved disclosures preserved');
select throws_ok($$select public.accept_current_event_policies_if_current('16160000-0000-4000-8000-000000000010',public.get_owned_event_change_context('16160000-0000-4000-8000-000000000010')->>'context_token')$$,'P0001','POLICY_ENVIRONMENT_UNCONFIGURED','consent still blocked');
select throws_ok($$select public.publish_event_if_current('16160000-0000-4000-8000-000000000010',public.get_owned_event_change_context('16160000-0000-4000-8000-000000000010')->>'context_token')$$,'P0001','POLICY_ENVIRONMENT_UNCONFIGURED','publication still blocked');
select set_config('request.jwt.claim.sub','16160000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.get_owned_event_change_context('16160000-0000-4000-8000-000000000010')$$,'P0001','EVENT_NOT_FOUND','foreign organizer cannot read context');
select throws_ok($$select public.save_owned_event_revision_if_current('16160000-0000-4000-8000-000000000010','{"title":"Foreign edit"}'::jsonb,'wrong-token')$$,'P0001','EVENT_NOT_FOUND','foreign organizer cannot write context');
reset role;
select is((select environment from private.organizer_policy_release_settings where singleton_id),'unconfigured','environment remains unconfigured');
select is((select count(*) from private.event_policy_acceptances where event_id='16160000-0000-4000-8000-000000000010'),0::bigint,'no policy acceptance created');
select set_config('request.jwt.claim.sub','',true);
set local role anon;
select throws_ok($$select public.get_owned_event_change_context('16160000-0000-4000-8000-000000000010')$$,'42501',null,'anonymous cannot execute context reader');
reset role;
select private.configure_policy_environment('development');
select set_config('request.jwt.claim.sub','16160000-0000-4000-8000-000000000001',true);
set local role authenticated;
select is(public.get_owned_event_change_context('16160000-0000-4000-8000-000000000010')->'requirements'->>'organizer_terms_version_id','dev-organizer-terms-v1','configured path retains original requirements contract');
select * from finish();
rollback;
